// CSD_RATIONALE_BEGIN
// Strategy: Start from attempt 43's proven 52%-accuracy structure, then insert
// RegenerateUnitOnGroundingFailure as Phase 3 between the forced-open (Phase 2)
// and the fallback close loop (Phase 4/5).
//
// Root cause of the 48% failure rate (141/300 semantic mismatches):
//   The parser enforces SQL grammar structure but not schema validity. When the
//   model emits aliases ("v", "dp") or hallucinated table names ("degree" instead
//   of "degree_programs"), the constrained span is syntactically valid SQL but
//   semantically wrong. GroupBoostedConstrainedStep with boost 6.0 favors schema
//   tokens but cannot prevent strong hallucination.
//
// Fix: After forcing << (Phase 2), call RegenerateUnitOnGroundingFailure with
//   budget = min(maxSteps - steps - 2, 500). This helper generates unit-by-unit,
//   detects ungrounded identifiers via lm.FirstUngroundedIdentifierTokenIdx,
//   rolls back to the last accepted checkpoint, and persistently penalizes the
//   bad identifier before resampling. maxRetries=3, maxRollbackBudget=15 lets
//   it recover from up to 3 bad table/column choices per query.
//
// Preserved from attempt 43 (best at 52%):
//   - 5-step unconstrained preamble (lets model emit "SQL: " prefix naturally)
//   - Force-open Phase 2 with OpenConstrainedSpan
//   - GroupBoostedConstrainedStep(6.0) fallback loop (Phase 4)
//   - CloseSpanWithinBudget(≤80) safety net (Phase 5)
//   - RenderedEndsWith for delimiter detection (never next == "<<")
//
// Phase 3 guard: only runs when currentConstrainedOut == [] (just opened span),
//   simplifying the length-invariant proof and ensuring the stable prefix is
//   exactly generated (no suffix reconstruction needed).
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1: parser_validity
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 (preamble): Loop guard includes !insideConstrainedOut. When
//   RenderedEndsWith("<<") fires, we set currentConstrainedOut := [] which
//   satisfies IsValidPrefix([]) by method precondition. EOS leaves
//   insideConstrainedOut false (implication vacuous). ✓
//
// Phase 2 (OpenConstrainedSpan): Runs only when !insideConstrainedOut.
//   Sets currentConstrainedOut := []; IsValidPrefix([]) by precondition. ✓
//
// Phase 3 (RegenerateUnitOnGroundingFailure): Runs only when
//   insideConstrainedOut && currentConstrainedOut == []. Postcondition guarantees
//   parser.IsValidPrefix(currentOut). We set currentConstrainedOut := currentOut,
//   so the invariant is re-established. insideConstrainedOut stays true (helper
//   does not close the span). ✓
//
// Phase 4 loop:
//   IsCompletePrefix branch: CloseConstrainedSpan sets insideConstrainedOut :=
//     false, making implication vacuous; currentConstrainedOut := []. ✓
//   Normal step: GroupBoostedConstrainedStep hard-masks to parser-valid tokens
//     plus EOS. AppendConstrainedToken extends currentConstrainedOut by one
//     parser-valid token, preserving IsValidPrefix by the extension contract. ✓
//   EOS+complete path: CloseConstrainedSpan sets insideConstrainedOut := false. ✓
//   EOS+incomplete path: break without mutation; invariant from last iteration. ✓
//
// Phase 5 (CloseSpanWithinBudget): Postcondition guarantees
//   insideOut ==> parser.IsValidPrefix(currentOut). ✓
//
// Invariant 2: progress  |generated| <= |generatedPrefix| + steps
//
// Phase 1: UnconstrainedStep increments steps by 1; generated grows by ≤1
//   (0 on EOS, 1 on non-EOS). Net ≤1:1. ✓
//
// Phase 2: OpenConstrainedSpan increments steps by 1; appends exactly "<<".
//   Net 1:1. ✓
//
// Phase 3: stepsUsed <= budget (helper postcondition). |currentOut| <= stepsUsed
//   (each forward step generates at most 1 token; rollbacks reduce the count,
//   never increase it). Since currentConstrainedOut == [] (guard), stablePrefix
//   = generated, so generated := generated + currentOut grows by |currentOut|
//   <= stepsUsed while steps grows by stepsUsed. Net ≤1:1 per step. ✓
//
// Phase 4 loop: GroupBoostedConstrainedStep increments steps by 1 (counts EOS
//   and constrained tokens alike). AppendConstrainedToken appends exactly 1
//   token. CloseConstrainedSpan appends ≤1 ">>" and costs 1 step. On EOS+close,
//   steps grows by 2 while generated grows by ≤1. All paths: ≤1 token per 1
//   step, plus a second step that at most closes with ">>". ✓
//   decreases: steps increments by ≥1 per iteration (always before any break). ✓
//
// Phase 5: |generatedOut| <= |generated| + closeBudget (helper postcondition).
//   steps grows by closeBudget. Net ≤1:1. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Output SQL: <<query>> where query is a valid SQL SELECT statement using ONLY the exact table and column names from the provided schema. The SQL must be placed between << and >>. No explanation, no markdown.");

var steps: nat := 0;

// Phase 1: Short preamble (at most 5 steps) to let model emit "SQL: " prefix
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if not already inside constrained span
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Schema-grounded SQL generation using RegenerateUnitOnGroundingFailure.
// Guard: only when we just opened the span (currentConstrainedOut == []) so that
// the stable prefix equals generated exactly, enabling the simple length update.
if insideConstrainedOut && currentConstrainedOut == [] && steps < maxSteps {
  var remaining := maxSteps - steps;
  var budget: nat;
  if remaining > 2 {
    var avail := remaining - 2;
    if avail <= 500 { budget := avail; } else { budget := 500; }
  } else {
    budget := 0;
  }
  if budget > 0 {
    // stablePrefix == generated because currentConstrainedOut == []
    var constrainedPrompt := prompt + generated;
    var currentOut, hitEos, stepsUsed := helpers.RegenerateUnitOnGroundingFailure(
      lm, parser, constrainedPrompt, currentConstrainedOut, eosToken, budget, 3, 15
    );
    steps := steps + stepsUsed;
    generated := generated + currentOut;
    currentConstrainedOut := currentOut;
  }
}

// Phase 4: Continue generating if span not yet complete (GroupBoosted fallback loop)
while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
    break;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.GroupBoostedConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 6.0, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      if parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
        var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + 1;
      }
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

// Phase 5: If span still open and budget remains, use CloseSpanWithinBudget
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var closeBudget: nat;
  if remaining <= 80 { closeBudget := remaining; } else { closeBudget := 80; }
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + closeBudget;
}

cost := steps;

